'use strict';

/* ─── About this file ─────────────────────────────────────────────────────────
 * Persistent scammer infraction store (data/scammer-list.json), keyed by Discord
 * user ID so it survives username and display-name changes. Written by
 * takeScamAction; read and managed through /scam-record.
 * Exports: recordInfraction, updateInfractionActions, updateInfractionEvidence,
 *          getRecord, getAllRecords, clearUser, trimInfractions
 * ────────────────────────────────────────────────────────────────────────── */

// ----- Contents (generated by `npm run index` — do not edit) -----
// L29     ROOT_DIR
// L30     STORE_PATH
